import type { ChannelOperationSourceV1 } from "./channel-operation-bindings.js";

/** A user goal and its provenance, distinct from the concrete command generated by Host. */
export interface ChannelNodeFunctionGoalV1 {
  readonly kind: "node_function";
  readonly modulePath: string;
  readonly invocation: string;
  readonly inputOperationId?: string;
  readonly sourceRefs: readonly ChannelOperationSourceV1[];
}

type JsonLiteral = null | boolean | number | string | readonly JsonLiteral[] | { readonly [key: string]: JsonLiteral };

/** No eval or expression rewriting: arguments must be bounded JSON literals. */
export function parseNodeFunctionInvocation(invocation: string): { readonly name: string; readonly args: readonly JsonLiteral[] } | undefined {
  if (typeof invocation !== "string" || invocation.length > 256 || /[\r\n\0]/u.test(invocation)) return undefined;
  const match = /^([A-Za-z_$][A-Za-z0-9_$]*)\s*\((.*)\)$/u.exec(invocation.trim());
  if (!match) return undefined;
  try {
    const args: unknown = JSON.parse(`[${match[2]}]`);
    if (!Array.isArray(args) || args.length > 32 || !isLiteral(args, 0)) return undefined;
    return { name: match[1]!, args };
  } catch { return undefined; }
}

function isLiteral(value: unknown, depth: number): value is JsonLiteral {
  if (depth > 16) return false;
  if (value === null || typeof value === "string" || typeof value === "boolean") return true;
  if (typeof value === "number") return Number.isFinite(value);
  if (typeof value !== "object") return false;
  return Object.values(value).every(item => isLiteral(item, depth + 1));
}

/** Deterministic payload shared by binding, persistence validation and execution matching. */
export function nodeFunctionGoalCommand(goal: Pick<ChannelNodeFunctionGoalV1, "modulePath" | "invocation">): string | undefined {
  const call = parseNodeFunctionInvocation(goal.invocation);
  const path = goal.modulePath;
  if (!call || typeof path !== "string" || !path || path.startsWith("/") || /[\\\u0000-\u001f:*?]/u.test(path)
    || path.split("/").some(part => !part || part === "." || part === "..")) return undefined;
  // Encode URL-significant path characters before dynamic import. Shell quoting
  // is a separate layer, and never authorizes the input file or command effect.
  let moduleUrl: string;
  try { moduleUrl = "./" + path.split("/").map(encodeURIComponent).join("/"); }
  catch { return undefined; } // A lone UTF-16 surrogate is not a filesystem URL.
  const script = `const m=await import(${JSON.stringify(moduleUrl)});const k=${JSON.stringify(call.name)};`
    + `const f=Object.hasOwn(m,k)?m[k]:Object.hasOwn(m.default??{},k)?m.default[k]:null;`
    + `if(typeof f!=="function")throw Error("missing export");console.log(await f(...${JSON.stringify(call.args)}));`;
  const command = "node --input-type=module -e '" + script.replaceAll("'", "'\"'\"'") + "'";
  return command.length <= 512 ? command : undefined;
}
